using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
public sealed class DeletedRecord {public string id="",kind="",deletedAt="";public int position;public WorkTask task;public CalendarEvent appointment;}
internal static class DeletionHistory {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};
 static T Clone<T>(T value){return Json.Deserialize<T>(Json.Serialize(value));}
 internal static void Validate(Data d){if(d.deleted==null)d.deleted=new List<DeletedRecord>();if(d.deleted.Count>50)throw new InvalidDataException("Historique des suppressions trop volumineux.");var ids=new HashSet<string>();foreach(var r in d.deleted){if(r==null||!new[]{"task","event"}.Contains(r.kind)||r.position<0)throw new InvalidDataException("Historique de suppression invalide.");if(String.IsNullOrEmpty(r.id)||!ids.Add(r.id)){r.id=Guid.NewGuid().ToString();ids.Add(r.id);}if(r.kind=="task"){if(r.task==null)throw new InvalidDataException("Tâche supprimée invalide.");Store.Validate(new Data{tasks=new List<WorkTask>{r.task}});}else{if(r.appointment==null)throw new InvalidDataException("Rendez-vous supprimé invalide.");Store.Validate(new Data{events=new List<CalendarEvent>{r.appointment}});}}}
 internal static DeletedRecord Remove(Data d,string kind,string id){var r=new DeletedRecord{id=Guid.NewGuid().ToString(),kind=kind,deletedAt=DateTime.Now.ToString("o")};if(kind=="task"){var t=d.tasks.FirstOrDefault(candidate=>candidate.id==id);if(t==null)return null;r.position=d.tasks.IndexOf(t);r.task=Clone(t);d.tasks.Remove(t);}else if(kind=="event"){var e=d.events.FirstOrDefault(candidate=>candidate.id==id);if(e==null)return null;r.position=d.events.IndexOf(e);r.appointment=Clone(e);d.events.Remove(e);}else throw new InvalidDataException("Type de suppression invalide.");d.deleted.Insert(0,r);if(d.deleted.Count>50)d.deleted.RemoveAt(d.deleted.Count-1);return r;}
 internal static string Title(DeletedRecord r){return r.kind=="task"?r.task.title:r.appointment.title;}
 internal static void Restore(Data d,string id){var r=d.deleted.FirstOrDefault(candidate=>candidate.id==id);if(r==null)throw new InvalidOperationException("Cette suppression n’est plus dans l’historique.");if(r.kind=="task"){if(d.tasks.Any(t=>t.id==r.task.id))throw new InvalidOperationException("Une tâche avec cet identifiant existe déjà.");d.tasks.Insert(Math.Min(r.position,d.tasks.Count),Clone(r.task));}else{if(d.events.Any(e=>e.id==r.appointment.id))throw new InvalidOperationException("Un rendez-vous avec cet identifiant existe déjà.");d.events.Insert(Math.Min(r.position,d.events.Count),Clone(r.appointment));}d.deleted.Remove(r);}
 internal static bool PersistChange(Data d,Action mutate,Func<bool> save){var tasks=d.tasks.ToList();var events=d.events.ToList();var history=d.deleted.ToList();try{mutate();if(save())return true;}catch{d.tasks=tasks;d.events=events;d.deleted=history;throw;}d.tasks=tasks;d.events=events;d.deleted=history;return false;}
 internal static void Test(string folder){var d=new Data();var t=new WorkTask{id="undo-task",title="Récurrence à récupérer",project="Personnel",status="done",priority="Haute",due="2026-10-20",repeat="weekly",nextId="already-created",notes="Notes",remindMinutes=15,lastReminder="sent"};d.tasks.Add(t);d.favorites.Add(new Favorite{kind="task",id=t.id});d.events.Add(new CalendarEvent{id="undo-event",title="Rendez-vous",date="2026-10-20",time="10:00",lastReminder="sent"});Store.Validate(d);var r=Remove(d,"task",t.id);if(d.tasks.Count!=0||GlobalSearch.Resolve(d,d.favorites[0])!=null)throw new Exception("Suppression ou favori");Restore(d,r.id);if(d.tasks[0].nextId!="already-created"||d.tasks[0].lastReminder!="sent"||GlobalSearch.Resolve(d,d.favorites[0])==null)throw new Exception("Restitution récurrence / rappel / favori");var e=Remove(d,"event","undo-event");Restore(d,e.id);if(d.events[0].lastReminder!="sent")throw new Exception("Restauration rendez-vous");if(PersistChange(d,()=>Remove(d,"task",t.id),()=>false)||d.tasks.Count!=1||d.deleted.Count!=0)throw new Exception("Retour arrière si sauvegarde refusée");var record=Remove(d,"task",t.id);var store=new Store(Path.Combine(folder,"deletions"));store.Value=d;store.Save();store=new Store(store.Root);Restore(store.Value,record.id);store.Save();if(store.Value.tasks.Count!=1||store.Value.deleted.Count!=0)throw new Exception("Historique persistant");for(int i=0;i<55;i++){var item=new WorkTask{id="cap-"+i,title="Tâche",project="Personnel",status="todo",priority="Normale"};d.tasks.Add(item);Remove(d,"task",item.id);}if(d.deleted.Count!=50)throw new Exception("Limite historique");}
}
